def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1

    color = min(counts, key=counts.get)
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == color]
    min_r = min(r for r, c in points)
    max_r = max(r for r, c in points)
    min_c = min(c for r, c in points)
    max_c = max(c for r, c in points)
    shape = [(r - min_r, c - min_c) for r, c in points]
    sh, sw = max_r - min_r + 1, max_c - min_c + 1

    out = [row[:] for row in grid]
    for top in range(h - sh + 1):
        for left in range(w - sw + 1):
            if all(grid[top + r][left + c] == 0 for r, c in shape):
                for r, c in shape:
                    out[top + r][left + c] = color
    return out
